cd /workspace/target && python3 - << 'PY'
import json
summary = {
  "candidate_hash": "df6596664871a87b0994d833e540e9fab603029cab76c26a4af7b5024955ae71",
  "code_hash": "6d8f6ccdf6e740f43622ecc61516d938f5c7273423a4b4c12c3d304eb48b8c31",
  "evidence": [
    {
      "id": "ev-55bf0e07f977307d",
      "observation": "Four history exports use mixed delimiters (comma, semicolon, pipe, comma), two require column renames, and one percent-scales weather to 0-100. Profile reports 11611 raw rows versus 11539 unique instants and weather_max 100, so concatenation without scale rules and instant deduplication corrupts both identity and weather features."
    },
    {
      "id": "ev-aeb536b5e01274ca",
      "observation": "Labeled history carries casual, registered, and cnt, but terminal requests omit all three. Those outcomes must never be predictors; only issue-time calendar and weather fields may enter the model."
    },
    {
      "id": "ev-867580c55d072abe",
      "observation": "Paired months show year-1 demand roughly 1.8x to 2.5x year-0 (January 55.5 to 130.6, March 87.7 to 221.9, April 131.9 to 242.7). Terminal year index is 1, so a model that treats yr as an unobserved extrapolation or pools years without a growth bridge will miss the 2012 level."
    },
    {
      "id": "ev-374a660d2d488e62",
      "observation": "Working-day commute hours 7, 8, 9, 16, 17, and 18 are sharp peaks, and year-1 peaks are much higher (hour 8: 350 to 521; hour 17: 395 to 529). A linear hour code cannot represent the commute shape that the protected MAE grades."
    },
    {
      "id": "ev-bd0a571e04d5a3f2",
      "observation": "Visible history ends 2012-04-30 while the terminal horizon is 2012-09-01 through 2012-12-31 (2888 rows, months 9-12). Same-hour weather is available at issue time, but no 2012 September-December labels exist in the frozen history, so the model must transfer seasonal structure from 2011 and year-1 growth rather than interpolate within 2012 fall."
    }
  ],
  "hypothesis": "The release fails because history is not normalized to the registry (scale, rename, instant dedupe), the retrospective mean model ignores the year-over-year demand bridge and working-day commute shape, and a 20th-percentile absolute residual is not an 80 percent forward interval. A model trained only through April 2012 must carry 2011 seasonal month effects across the four-month gap, scaled by the observed year-1 growth, with hour interactions for commute peaks and 80 percent intervals calibrated from chronological forward residuals.",
  "planned_test": "After commitment, normalize exports to 11539 unique rows with weather on 0-1, fit a chronological model with year-bridge and commute-hour features, calibrate 80 percent intervals from forward residuals, and check public March-April rehearsal plus permutation invariance before the protected replay. Target overall RMSE <= 65, month RMSE <= 72, commute MAE <= 76, coverage 70-98 percent, and mean width <= 250."
}
path = "/tmp/investigation.json"
with open(path, "w", encoding="ascii") as handle:
    json.dump(summary, handle, indent=2)
    handle.write("\n")
print("wrote", path, "bytes", len(json.dumps(summary)))
PY
python3 env_cli.py hypothesis.commit --evidence ev-55bf0e07f977307d ev-aeb536b5e01274ca ev-867580c55d072abe ev-374a660d2d488e62 ev-bd0a571e04d5a3f2 --summary-file /tmp/investigation.json

